// Parse AI response and validate output
// Returns structured invoice data or error object

try {
  const aiResponse = $input.item.json;
  const rawContent = aiResponse.choices?.[0]?.message?.content;

  if (!rawContent) {
    return [{
      json: {
        _error: true,
        error_type: 'empty_ai_response',
        error_message: 'OpenAI returned empty content',
        raw_ai_output: JSON.stringify(aiResponse)
      }
    }];
  }

  // Strip markdown code fences if AI added them despite instructions
  const cleaned = rawContent
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch (parseErr) {
    return [{
      json: {
        _error: true,
        error_type: 'parse_failed',
        error_message: 'Could not parse AI JSON output: ' + parseErr.message,
        raw_ai_output: rawContent
      }
    }];
  }

  // Validate at least one meaningful field was extracted
  const hasData = parsed.vendor || parsed.invoice_number || parsed.total_amount;
  if (!hasData) {
    return [{
      json: {
        _error: true,
        error_type: 'no_data_extracted',
        error_message: 'AI returned JSON but no invoice fields were found',
        raw_ai_output: rawContent
      }
    }];
  }

  // Normalize line_items to always be an array
  if (!Array.isArray(parsed.line_items)) {
    parsed.line_items = [];
  }

  // Return clean parsed data
  return [{ json: { _error: false, ...parsed } }];

} catch (err) {
  return [{
    json: {
      _error: true,
      error_type: 'unexpected_error',
      error_message: err.message,
      raw_ai_output: null
    }
  }];
}
